begin;
create temporary table chat_test(a uuid,b uuid,c uuid,sid uuid,code text,msg uuid,ownmsg uuid,photo uuid);
insert into chat_test values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null,gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id,aud,role,email) select a,'authenticated','authenticated',a::text||'@chat-test.invalid' from chat_test union all select b,'authenticated','authenticated',b::text||'@chat-test.invalid' from chat_test union all select c,'authenticated','authenticated',c::text||'@chat-test.invalid' from chat_test;
grant select,update on chat_test to authenticated;
create function pg_temp.assert_chat(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from chat_test;
update chat_test set sid=public.create_partner_space_with_role('user_1');
update chat_test set code=public.issue_pair_code()->>'code';
select public.mutate_shared_record(msg,sid,'appreciation',null,null,'{"kind":"Message","message":"Chat test","taskTitle":"","picture":"","at":1}'::jsonb,0,msg,false) from chat_test;
select public.mutate_shared_record(photo,sid,'appreciation',null,null,'{"kind":"Locket","message":"Photo","taskTitle":"","picture":"","at":1}'::jsonb,0,photo,false) from chat_test;
select pg_temp.assert_chat(public.mark_chat_read(sid,array[msg])=0,'sender cannot mark own message Read') from chat_test;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from chat_test;
select public.redeem_pair_code_with_role(code,'user_2') from chat_test;
select pg_temp.assert_chat(public.mark_chat_read(sid,array[msg])=1,'recipient marks partner message Read') from chat_test;
select pg_temp.assert_chat(public.mark_chat_read(sid,array[msg])=0,'repeated receipt is idempotent') from chat_test;
select pg_temp.assert_chat(public.mark_chat_read(sid,array[photo])=0,'Locket does not get chat receipt') from chat_test;
select public.mutate_shared_record(ownmsg,sid,'appreciation',null,null,'{"kind":"Message","message":"Reply","taskTitle":"","picture":"","at":2}'::jsonb,0,ownmsg,false) from chat_test;
do $$declare t chat_test%rowtype;begin select * into t from chat_test;
 begin insert into public.chat_read_receipts(message_id,reader_id,space_id) values(t.ownmsg,t.a,t.sid);raise exception 'FAILED: forged partner receipt accepted';exception when insufficient_privilege then null;end;
 begin update public.chat_read_receipts set read_at=now();raise exception 'FAILED: receipts mutable';exception when insufficient_privilege then null;end;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from chat_test;
select pg_temp.assert_chat((select count(*) from public.chat_read_receipts where reader_id=(select b from chat_test))=1,'sender sees genuine partner receipt');
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true) from chat_test;
select pg_temp.assert_chat((select count(*) from public.chat_read_receipts)=0,'outsider cannot read receipts');
do $$declare t chat_test%rowtype;begin select * into t from chat_test;
 begin perform public.mark_chat_read(t.sid,array[t.msg]);raise exception 'FAILED: outsider can acknowledge';exception when insufficient_privilege then null;end;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from chat_test;
select public.leave_partner_space();
select pg_temp.assert_chat((select count(*) from public.chat_read_receipts)=0,'unpair immediately revokes receipt reads');
set local role anon;
do $$begin
 begin perform * from public.chat_read_receipts;raise exception 'FAILED: anonymous read';exception when insufficient_privilege then null;end;
end$$;
reset role;
select 'Chat receipt authorization, sender visibility, idempotence and unpair tests passed; all fixtures rolled back.' as result;
rollback;
